import permutationsHeap from '../../src/permutations_heap';

describe('permutationsHeap', () => {
  it('should return an empty array for empty input', () => {
    expect(permutationsHeap([])).toEqual([[]]);
  });

  it('should return single permutation for single element', () => {
    const input = [1];
    const expected = [[1]];
    expect(permutationsHeap(input)).toEqual(expected);
  });

  it('should generate all permutations for two elements', () => {
    const input = [1, 2];
    const expected = [
      [1, 2],
      [2, 1]
    ];
    expect(permutationsHeap(input)).toEqual(expect.arrayContaining(expected));
    expect(permutationsHeap(input).length).toBe(2);
  });

  it('should generate all permutations for three distinct elements', () => {
    const input = [1, 2, 3];
    const result = permutationsHeap(input);

    // There should be 3! = 6 permutations
    expect(result.length).toBe(6);

    // Check if the original array's permutations are present
    const expected = [
      [1, 2, 3],
      [2, 1, 3],
      [3, 1, 2],
      [1, 3, 2],
      [2, 3, 1],
      [3, 2, 1]
    ];

    expect(result).toEqual(expect.arrayContaining(expected));
  });

  it('should handle duplicate elements in the input array (generates N! permutations including duplicates)', () => {
    const input = [1, 1];
    const result = permutationsHeap(input);

    // Heap's algorithm generates N! permutations based on positions, not values
    expect(result.length).toBe(2);
    expect(result[0]).toEqual([1, 1]);
    expect(result[1]).toEqual([1, 1]);
  });

  it('should handle input with mixed types (numbers and strings)', () => {
    const input = [1, 'a', 2];
    const result = permutationsHeap(input);
    expect(result.length).toBe(6);

    // Verify a few specific permutations exist
    expect(result).toContainEqual([1, 'a', 2]);
    expect(result).toContainEqual([2, 'a', 1]);
    expect(result).toContainEqual(['a', 1, 2]);
  });

  it('should mutate the original input array', () => {
    const input = [1, 2, 3];
    const originalCopy = [...input];

    permutationsHeap(input);

    // The function implementation performs in-place swaps, mutating the input array
    expect(input).not.toEqual(originalCopy);
  });
});
